:root{--deck-background:#eef3fc;--deck-ink:#132a56;--deck-accent:#325dd8;--deck-secondary:#c6d8fa;}
* { box-sizing: border-box; }
body {
  margin: 0;
  padding: clamp(12px, 3vw, 32px);
  color: var(--deck-ink);
  background: color-mix(in srgb, var(--deck-background) 87%, var(--deck-ink));
  font: 16px/1.5 system-ui, "Microsoft YaHei", sans-serif;
}
.deck-shell {
  max-width: 1080px;
  margin: 0 auto;
  overflow: hidden;
  border-radius: 14px;
  background: var(--deck-background);
}
.deck-slide {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: clamp(16px, 5vw, 54px);
  aspect-ratio: 16 / 9;
  padding: clamp(23px, 6vw, 76px);
}
.deck-slide[hidden] { display: none; }
.deck-cover {
  position: relative;
  justify-content: center;
  background:
    radial-gradient(ellipse at 92% 16%, var(--deck-secondary), transparent 46%),
    var(--deck-background);
}
.deck-cover .deck-copy, .deck-cover .deck-items { position: relative; z-index: 1; }
.deck-cover .deck-copy { max-width: 65%; }
.deck-cover-art { position: absolute; inset: 15% 6% 13% 68%; display: flex; gap: 7%; align-items: end; }
.deck-cover-art i {
  flex: 1;
  height: 38%;
  border-radius: 5px 5px 0 0;
  background: linear-gradient(var(--deck-accent),var(--deck-secondary));
}
.deck-cover-art i:nth-child(2) { height: 61%; }
.deck-cover-art i:nth-child(3) { height: 86%; }
.deck-theme-research .deck-cover-art i {
  position: absolute;
  inset: 22% 0 auto;
  height: auto;
  aspect-ratio: 1;
  border-radius: 50%;
  border: 1px solid var(--deck-accent);
  background: transparent;
}
.deck-theme-research .deck-cover-art i:first-child { background: var(--deck-secondary); transform: translate(-22%,-13%); }
.deck-theme-research .deck-cover-art i:last-child { transform: translate(17%,13%); }
.deck-theme-research .deck-cover .deck-copy {
  border-left: 2px solid var(--deck-accent);
  padding-left: clamp(14px, 3vw, 30px);
}
.deck-theme-launch .deck-cover {
  background:
    radial-gradient(ellipse at 85% 22%, var(--deck-secondary), transparent 60%),
    var(--deck-background);
}
.deck-theme-launch .deck-cover-art {
  inset: 16% 10% 16% 65%;
  border-radius: 45% 45% 14% 14%;
  border: 1px solid var(--deck-accent);
  background: radial-gradient(ellipse at 50% 68%,var(--deck-accent),var(--deck-secondary) 62%);
}
.deck-theme-launch .deck-cover-art i { display: none; }
h1, h2 { line-height: 1.12; margin: 0; overflow-wrap: anywhere; }
h1 { font-size: clamp(30px, 6.7vw, 75px); }
h2 { font-size: clamp(24px, 4.8vw, 50px); }
.deck-copy p { margin: 14px 0 0; max-width: 58ch; font-size: clamp(15px, 2vw, 22px); overflow-wrap: anywhere; }
.deck-items {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 145px), 1fr));
  gap: clamp(10px, 2vw, 22px);
  list-style: none;
  padding: 0;
  margin: 0;
}
.deck-items li {
  display: grid;
  align-content: start;
  gap: 8px;
  padding: clamp(12px, 2vw, 22px);
  background: color-mix(in srgb, var(--deck-secondary) 39%, var(--deck-background));
  border-top: 2px solid var(--deck-accent);
  border-radius: 7px;
  overflow-wrap: anywhere;
}
.deck-items strong { font-size: 1.05em; }
.deck-metrics .deck-items span { font-size: clamp(17px, 2.7vw, 30px); font-weight: 700; }
.deck-timeline .deck-items { counter-reset: phase; }
.deck-timeline .deck-items li { counter-increment: phase; }
.deck-timeline .deck-items li::before { content: counter(phase, decimal-leading-zero); font-size: .8em; font-weight: 700; }
.deck-nav {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: clamp(12px, 3vw, 30px);
  padding: 12px;
  border-top: 1px solid var(--deck-secondary);
}
.deck-nav output { font-variant-numeric: tabular-nums; }
.deck-nav button {
  min-height: 40px;
  border: 1px solid var(--deck-secondary);
  border-radius: 7px;
  padding: 5px 13px;
  color: var(--deck-ink);
  background: var(--deck-background);
  font: inherit;
  cursor: pointer;
}
.deck-nav button:hover:not(:disabled) { background: var(--deck-secondary); }
.deck-nav button:disabled { opacity: .45; cursor: default; }
.deck-nav button:focus-visible { outline: 2px solid var(--deck-accent); outline-offset: 2px; }
@media (max-width: 560px) {
  .deck-slide { aspect-ratio: auto; min-height: 240px; }
  .deck-cover .deck-copy { max-width: 82%; }
  .deck-cover-art { opacity: .35; }
}

